import {FISHING_SPOTS,FISHING_LURES,FISHING_SIGNALS,FISHING_ACTIONS,fishingSpot} from './fishing-data.js';
import {fishingProgress,fishingRank,fishingKnown,fishingHere} from './fishing.js';
import {CHAPTERS,SPECIES,ITEMS} from './data.js';
import {OUTDOOR_AREAS} from './outdoor-areas.js';
const portrait=(id,size=80)=>`<canvas width="${size*2}" height="${size*2}" style="width:${size}px;height:${size}px" data-species="${id}" aria-hidden="true"></canvas>`;
export const fishingLocation=s=>`${CHAPTERS[s.region].island} · ${OUTDOOR_AREAS[s.region].areas[s.sector].name}`;
const ranks=['初识水纹','稳流观察者','听潮记录员','星海知音'];
function waterscape(s,a){return `<svg class="fishing-vista" viewBox="0 0 760 210" role="img" aria-label="${s.name}的星浮与水纹"><defs><linearGradient id="float-sky" x2="0" y2="1"><stop stop-color="#253f51"/><stop offset="1" stop-color="${s.color}"/></linearGradient><linearGradient id="float-water" x2="0" y2="1"><stop stop-color="#527c83"/><stop offset="1" stop-color="#193f51"/></linearGradient></defs><rect width="760" height="210" fill="url(#float-sky)"/><circle cx="617" cy="43" r="24" fill="#efe5b7" opacity=".8"/><path d="M0 111 76 58 147 97 222 62 314 112 384 81 464 114 572 91 665 110 760 71V167H0Z" fill="#3a6168"/><path d="M0 119 120 101 268 120 399 113 556 128 760 106V210H0Z" fill="url(#float-water)"/><g stroke="#b3d1c0" stroke-width="2" opacity=".3"><path d="M105 148h109m245-10h114m-370 35h135m198 19h82m-32-35h58m-420 44h123"/></g><path d="M0 172 81 160 149 172 170 210H0Z" fill="#324e47"/><path d="M43 185 84 84Q157 46 221 75" fill="none" stroke="#c5aa7d" stroke-width="6"/><path d="M220 75Q${a?.tension>4?'272 85':'261 151'} 331 155" fill="none" stroke="#dfdcc1" stroke-width="1.5"/><ellipse cx="331" cy="169" rx="38" ry="8" fill="none" stroke="#bcd8c5" opacity=".4"/><ellipse cx="331" cy="169" rx="21" ry="4" fill="none" stroke="#e4e6c5" opacity=".6"/><path d="m331 145 5 12 12 5-12 5-5 12-5-12-12-5 12-5Z" fill="${a?.tension>4?'#e7a28b':'#e5d096'}"/><path d="M682 210v-50m0 20 12-18m-12 26-16-17m36 39v-38m0 12 10-17" stroke="#81a393" stroke-width="4"/><g fill="#e3dcae" opacity=".7"><circle cx="407" cy="39" r="1.5"/><circle cx="506" cy="58" r="1.5"/><circle cx="464" cy="20" r="2"/></g></svg>`;}
const records=(g,s)=>{const p=fishingProgress(g,s.id);return `<div class="shore-species">${s.families.map((f,i)=>`<div class="${p.catches[f]?'recorded':''}">${portrait(f,64)}<strong>${SPECIES[f].name}</strong><small>${p.catches[f]?'已在此缔约 '+p.catches[f]+' 次':i===1?'偏好草叶浮饵':i===2?'偏好果香浮饵':'星浮也能邀请'}</small></div>`).join('')}</div>`;};
export function fishingMarkup(game,id,lure='plain',feedback=''){
 const s=fishingSpot(id),a=game.fishing?.active,local=a?.spot===id?a:null,rank=fishingRank(game),signal=local&&FISHING_SIGNALS[local.signal];
 let content='';
 if(local?.phase==='line')content=`<div class="fishing-meters"><div><span>靠岸进度 <b>${local.progress} / 8</b></span><i><em style="width:${local.progress/8*100}%"></em></i><small>填满靠近进度，邀请它来到岸边</small></div><div class="line-tension"><span>钓线张力 <b>${local.tension} / ${local.limit}</b></span><i><em style="width:${local.tension/local.limit*100}%"></em></i><small>达到 ${local.limit} 时会脱线 · 第 ${local.turn+1} / 12 次鱼讯</small></div></div><div class="float-signal" role="status"><span>${signal.symbol}</span><div><small>现在的鱼讯</small><h3>${signal.name}</h3><p>${signal.hint}</p></div></div><div class="fishing-controls">${Object.entries(FISHING_ACTIONS).map(([key,v],i)=>`<button data-fish-action="${key}"><small>0${i+1}</small><strong>${v.name}</strong><span>${v.detail}</span></button>`).join('')}</div><p class="section-note">不用抢按。读懂鱼讯再选择；关闭窗口会保留这条钓线。</p><button id="fishing-abandon" class="text-button">收起这条线 · 已用浮饵不返还</button>`;
 else if(local?.phase==='landed')content=`<div class="shore-arrival">${portrait(local.family+(local.level>=32?'_3':local.level>=16?'_2':''),150)}<div><small>水岸相遇 · Lv.${local.level}</small><h3>${SPECIES[local.family+(local.level>=32?'_3':local.level>=16?'_2':'')].name}</h3><p>它愿意靠近你的星浮。正常对战并使用星约石缔约，才能记入这处水岸的同行记录。</p><div class="card-actions"><button class="primary" id="fishing-battle">邀请同行 →</button><button class="secondary" id="fishing-release">轻轻放回水中</button></div></div></div>`;
 else if(a)content=`<div class="shore-pending"><h3>还有一条未收好的线</h3><p>${fishingLocation(fishingSpot(a.spot))} · ${fishingSpot(a.spot).name}</p><p>可以回到那处水岸继续，也可以收起旧线，从这里重新开始。</p><button id="fishing-abandon" class="secondary">收起旧线</button></div>`;
 else content=`<div class="float-preparation"><div><span class="eyebrow">选择浮饵</span><p>没有鱼钩的星浮，邀请水边的伙伴来见面。特殊浮饵只在抛出时消耗一次。</p></div><div class="float-lures">${Object.entries(FISHING_LURES).map(([key,v])=>`<button data-fish-lure="${key}" class="${key===lure?'chosen':''}" aria-pressed="${key===lure}"><strong>${v.name}</strong><span>${v.item?ITEMS[v.item].name+' × 1 · 持有 '+(game.bag[v.item]||0):'无需消耗'}</span><small>${v.desc}</small></button>`).join('')}</div><button class="primary" id="fishing-cast" ${FISHING_LURES[lure].item&&!(game.bag[FISHING_LURES[lure].item]>0)?'disabled':''}>放下星浮 →</button></div>`;
 return `<div class="shore-heading"><div><small>${fishingLocation(s)}</small><h3>${s.name}</h3></div><span>${ranks[rank.rank]}<small>${rank.count} / 24 项缔约记录</small></span></div>${waterscape(s,local)}${feedback?`<p class="fishing-feedback" role="status">${feedback}</p>`:''}${content}<details class="shore-guide"><summary>潮伯的收线口诀</summary><p>急沉时松线，靠近时收线，遇浪时等待。正确观察让靠近进度增加 2；张力过高时，可以先松线。累计 4、12、24 项水岸记录，钓线的张力上限会逐级增加。十二次鱼讯后仍未靠岸，它就会暂时游远。</p></details><div class="shore-record-heading"><h3>这里的三位水岸伙伴</h3><button class="text-button" id="fishing-record">${s.angler}的记录 →</button></div>${records(game,s)}<button class="text-button" id="fishing-notebook">打开八岛水岸手册 →</button>`;
}
export function fishingNotebookMarkup(game){
 const rank=fishingRank(game),active=game.fishing?.active;
 return `<div class="shore-book-cover"><span class="eyebrow">${ranks[rank.rank]} · ${rank.count} / 24 项记录</span><h3>每一次靠岸，<br>都是一份愿意相信。</h3><p>八处星浮水岸，二十四份同行约定。在每处水岸缔约三种伙伴，听完当地渔人的故事，收下旅行补给。完成八份记录，还会获得纪念护符「澄潮结」。</p>${active?`<p class="shore-resume">未收好的星浮：${fishingSpot(active.spot).name}。回到原处可以继续。</p>`:''}</div><div class="shore-book-grid">${FISHING_SPOTS.filter(s=>fishingKnown(game,s)).map(s=>{const p=fishingProgress(game,s.id);return `<article style="--shore-color:${s.color}"><small>${fishingLocation(s)}</small><h3>${s.name}</h3><p>${s.angler}</p><div class="shore-dots">${s.families.map(f=>`<span class="${p.catches[f]?'done':''}">${p.catches[f]?'✓':'○'} ${SPECIES[f].name}</span>`).join('')}</div><button class="secondary" data-shore-record="${s.id}">${p.claimed?'重读水岸故事':p.ready?'交换完整记录':p.count+' / 3 · 查看水岸'}</button></article>`;}).join('')}</div><p class="section-note">新岛屿的水岸会在抵达后记入手册。已有的普通捕获不会冒充当地垂钓记录。</p><button class="text-button" id="fishing-dex">返回潮灵图鉴 →</button>`;
}
export function fishingRecordMarkup(game,id){
 const s=fishingSpot(id),p=fishingProgress(game,id),choice=game.fishing?.choices[id];
 return `<div class="shore-heading"><div><small>${fishingLocation(s)}</small><h3>${s.angler}</h3></div><span>${p.count} / 3 份记录</span></div><div class="shore-prose">${s.opening.map(t=>`<p>${t}</p>`).join('')}</div>${records(game,s)}${p.count===3?`<blockquote class="shore-ending">${s.ending}</blockquote>`:''}${p.claimed?`<div class="shore-choice-reply"><small>你当时说 · ${s.choices[choice].text}</small><p>${s.choices[choice].reply}</p></div><p class="section-note">水岸纪念已领取。</p>`:p.ready?`<div class="recipe-choices">${s.choices.map((c,i)=>`<button data-shore-choice="${i}">${c.text}<span>→</span></button>`).join('')}</div><p class="section-note">交换后获得辉光星约石 × 2、潮红果 × 4、银滩食盐 × 4。</p>`:'<p class="section-note">从这处水岸引来并缔约三种伙伴后，再回来一起写完这页故事。</p>'}<div class="card-actions"><button class="secondary" id="shore-chart">${fishingHere(game,s)?'在随身航图找到水岸':'打开群岛航图'}</button><button class="text-button" id="shore-book-back">返回八岛水岸手册</button></div>`;
}
